const rotor=document.querySelector("#rotor"),startButton=document.querySelector("#start"),pauseButton=document.querySelector("#pause"),reduceCheckbox=document.querySelector("#reduce"),status=document.querySelector("#status");let angle=0,speed=0,running=false,last=0,began=0,frame=0;function draw(){rotor.style.setProperty("--turn",`${angle}deg`)}function tick(now){if(!running)return;if(!last){last=now;began=now}const progress=Math.min(1,(now-began)/3200);speed=.06+.94*(1-Math.pow(1-progress,3));angle=(angle+(now-last)*speed*.01)%360;last=now;draw();status.textContent=progress<1?"The wheel slowly gathers momentum.":"The wheel turns; its carriages remain upright.";frame=requestAnimationFrame(tick)}function pauseWheel(message="Wheel motion paused."){running=false;cancelAnimationFrame(frame);last=0;startButton.textContent="Resume wheel";pauseButton.disabled=true;status.textContent=message}function startWheel(){if(reduceCheckbox.checked)return;running=true;last=0;began=0;startButton.textContent="Restart acceleration";pauseButton.disabled=false;frame=requestAnimationFrame(tick)}function applyMotionPreference(){if(reduceCheckbox.checked){pauseWheel("Reduced motion: wheel and carriages remain still.");startButton.disabled=true}else{startButton.disabled=false;pauseWheel("Wheel motion is stopped.")}}startButton.addEventListener("click",startWheel);pauseButton.addEventListener("click",()=>pauseWheel());reduceCheckbox.addEventListener("change",applyMotionPreference);reduceCheckbox.checked=window.matchMedia("(prefers-reduced-motion: reduce)").matches;applyMotionPreference();draw();
